$ErrorActionPreference = "Stop"

Write-Host "=== SaborFlow - Etapa 13.2 - 2FA TOTP ===" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path "package.json")) {
    throw "Execute este script na pasta principal do projeto SaborFlow."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $env:TEMP "SaborFlow-Etapa13-2-Backup-$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$replaceFiles = @(
    "app\api\auth\login\route.ts",
    "app\api\auth\google\route.ts",
    "components\admin\login-form.tsx"
)

foreach ($file in $replaceFiles) {
    if (Test-Path $file) {
        $backupPath = Join-Path $backupRoot $file
        $backupDir = Split-Path $backupPath -Parent
        New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
        Copy-Item $file $backupPath -Force
    }
}

Write-Host "Backup criado em:" -ForegroundColor Green
Write-Host $backupRoot
Write-Host ""

Write-Host "Instalando dependencia local para gerar QR Code..." -ForegroundColor Yellow
& npm.cmd install qrcode
if ($LASTEXITCODE -ne 0) {
    throw "Falha ao instalar qrcode."
}

& npm.cmd install -D @types/qrcode
if ($LASTEXITCODE -ne 0) {
    throw "Falha ao instalar @types/qrcode."
}

function Write-Base64File {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][string]$Base64
    )

    $directory = Split-Path $Path -Parent
    if ($directory) {
        New-Item -ItemType Directory -Force -Path $directory | Out-Null
    }

    $bytes = [Convert]::FromBase64String($Base64)
    [IO.File]::WriteAllBytes((Join-Path (Get-Location) $Path), $bytes)
}

Write-Host "Gravando database\migrations\028_admin_totp_2fa.sql..."
Write-Base64File -Path "database\migrations\028_admin_totp_2fa.sql" -Base64 ""

Write-Host "Gravando lib\security\two-factor-challenge.ts..."
Write-Base64File -Path "lib\security\two-factor-challenge.ts" -Base64 ""

Write-Host "Gravando lib\security\two-factor.ts..."
Write-Base64File -Path "lib\security\two-factor.ts" -Base64 ""

Write-Host "Gravando app\api\auth\2fa\setup\route.ts..."
Write-Base64File -Path "app\api\auth\2fa\setup\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\2fa\qr\route.ts..."
Write-Base64File -Path "app\api\auth\2fa\qr\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\2fa\verify\route.ts..."
Write-Base64File -Path "app\api\auth\2fa\verify\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\login\route.ts..."
Write-Base64File -Path "app\api\auth\login\route.ts" -Base64 ""

Write-Host "Gravando app\api\auth\google\route.ts..."
Write-Base64File -Path "app\api\auth\google\route.ts" -Base64 ""

Write-Host "Gravando components\admin\login-form.tsx..."
Write-Base64File -Path "components\admin\login-form.tsx" -Base64 ""

Write-Host ""
Write-Host "Arquivos da Etapa 13.2 aplicados." -ForegroundColor Green
